<div class="admin-page-actions"><div><span class="admin-kicker">Pedido #<?=e($order['id_pedido'])?></span><h2>Detalle del pedido</h2><p><?=e((new DateTimeImmutable($order['fecha_pedido']))->format('d/m/Y H:i'))?> · <?=e($order['cliente'])?></p></div><a class="admin-secondary-button" href="<?=e(url('admin-orders'))?>">Volver</a></div><div class="admin-detail-grid"><section class="admin-panel"><h3>Productos</h3><ul class="admin-order-products"><?php foreach($order['items'] as $item):?><li><span><?=e($item['cantidad'])?> × <?=e($item['nombre'])?></span><strong><?=e(money($item['subtotal']))?></strong></li><?php endforeach;?></ul><div class="admin-total"><span>Total</span><strong><?=e(money($order['total']))?></strong></div></section><aside class="admin-panel"><h3>Cliente y entrega</h3><dl class="admin-definition"><dt>Cliente</dt><dd><?=e($order['cliente'])?></dd><dt>Correo</dt><dd><?=e($order['correo'])?></dd><dt>Teléfono</dt><dd><?=e($order['telefono']??'No informado')?></dd><dt>Dirección</dt><dd><?=e($order['direccion']??'No informada')?></dd></dl></aside></div><div class="admin-detail-grid mt-4"><section class="admin-panel"><h3>Estado del pedido</h3><form method="post" action="<?=e(url('admin-order-update',['id'=>$order['id_pedido']]))?>"><?=csrf_input()?><label class="admin-field"><span>Estado</span><select class="form-select" name="estado"><?php foreach(['PENDIENTE','CONFIRMADO','PREPARANDO','ENTREGADO','CANCELADO'] as $state):?><option <?=$order['estado']===$state?'selected':''?>><?=e($state)?></option><?php endforeach;?></select></label><button class="admin-primary-button mt-3" type="submit">Actualizar pedido</button></form></section><section class="admin-panel"><h3>Pago</h3><dl class="admin-definition"><dt>Método</dt><dd><?=e($order['metodo']??'Sin pago')?></dd><dt>Estado</dt><dd><span class="admin-status"><?=e($order['pago_estado']??'SIN PAGO')?></span></dd><dt>Monto</dt><dd><?=e(money($order['monto']??0))?></dd><dt>Referencia</dt><dd><?=e($order['referencia_transaccion']??'—')?></dd><dt>Confirmado</dt><dd><?=e($order['fecha_confirmacion']??'Pendiente')?></dd></dl><?php if(!empty($order['comprobante_archivo'])):?><a class="admin-secondary-button mb-3" target="_blank" rel="noopener" href="<?=e(url('admin-payment-proof',['id'=>$order['id_pedido']]))?>">Ver comprobante</a><?php endif;?><?php if(($order['pago_estado']??null)==='PENDIENTE'):?><form method="post" action="<?=e(url('admin-payment-approve',['id'=>$order['id_pedido']]))?>"><?=csrf_input()?><button class="admin-primary-button" type="submit">Aprobar pago</button></form><?php endif;?></section></div>
